INSERT INTO `dc_cube_page` (`recipe_id`,`subtitle`,`item`,`note`,`quote`,`quote_source`) VALUES
('archive_of_tal_rasha','Extract Legendary Power','Legendary Item with Special Power','','...all agreed that the cube was necessary if the hunt for the three was to be successful. They thought they understood the dangers.','fragment of the Dark Exile Scrolls.'),
('caldesanns_despair','Augment Ancient Item','Ancient or Primal Item','Replaces the item''s earlier augment.','',''),
('curiosity_of_lorath_nahr','Upgrade Legendary Item','Legendary or Set Item','Only one upgraded Primal Item may be worn at a time.','',''),
('hope_of_cain','Upgrade Rare Item','Rare Item','','When the physical material of the cube was forged, the real work began. Ten Horadrim took it deep into the cave, to a place that should never have been disturbed.','fragment of the Dark Exile Scrolls.'),
('iben_pleasure','Convert Reusable Parts to Item''s Material','Normal, Magic or Rare Item','','',''),
('iben_regret','Convert Arcane Dust to Item''s Material','Normal, Magic or Rare Item','','',''),
('iben_wrath','Convert Veiled Crystal to Item''s Material','Normal, Magic or Rare Item','','',''),
('law_of_kulle','Reforge Legendary','Legendary or Set Item','','For weeks the fires burned, the smiths hammered and the mages chanted. Those who spent too long in the forge wandered, wide eyed and unblinking, in the daylight. They did not sleep.','fragment of the Dark Exile Scrolls.'),
('skill_of_nilfur','Convert Set Item','Set Item','Resulting item cannot be Ancient.','...of the cave, ten Horadrim channeled powers arcane and mystic. Ten felt their sanity slipping away. And nine averted their eyes as the cube came alive.','fragment of the Dark Exile Scrolls.');
